CREATE TABLE MWIPLOTRWK
(
    LOT_ID                      VARCHAR2(25)     DEFAULT(' ')    NOT NULL,
    HIST_SEQ                    NUMBER(10)       DEFAULT(0)      NOT NULL,
    TRAN_TIME                   VARCHAR2(14)     DEFAULT(' ')    NOT NULL,
    HIST_DEL_FLAG               CHAR(1)          DEFAULT(' ')    NOT NULL,
    FACTORY                     VARCHAR2(10)     DEFAULT(' ')    NOT NULL,
    MAT_ID                      VARCHAR2(30)     DEFAULT(' ')    NOT NULL,
    MAT_VER                     NUMBER(6)        DEFAULT(0)      NOT NULL,
    FLOW                        VARCHAR2(20)     DEFAULT(' ')    NOT NULL,
    FLOW_SEQ_NUM                NUMBER(6)        DEFAULT(0)      NOT NULL,
    OPER                        VARCHAR2(10)     DEFAULT(' ')    NOT NULL,
    RES_ID                      VARCHAR2(20)     DEFAULT(' ')    NOT NULL,
    CAUSE_FLOW                  VARCHAR2(20)     DEFAULT(' ')    NOT NULL,
    CAUSE_OPER                  VARCHAR2(10)     DEFAULT(' ')    NOT NULL,
    CAUSE_RES_ID                VARCHAR2(20)     DEFAULT(' ')    NOT NULL,
    QTY_1                       NUMBER(10,3)     DEFAULT(0.0)    NOT NULL,
    QTY_2                       NUMBER(10,3)     DEFAULT(0.0)    NOT NULL,
    QTY_3                       NUMBER(10,3)     DEFAULT(0.0)    NOT NULL,
    RWK_CODE                    VARCHAR2(10)     DEFAULT(' ')    NOT NULL,
    RWK_COUNT                   NUMBER(6)        DEFAULT(0)      NOT NULL,
    RWK_DEPTH                   NUMBER(6)        DEFAULT(0)      NOT NULL,
    RWK_FLOW                    VARCHAR2(20)     DEFAULT(' ')    NOT NULL,
    RWK_FLOW_SEQ_NUM            NUMBER(6)        DEFAULT(0)      NOT NULL,
    RWK_OPER                    VARCHAR2(10)     DEFAULT(' ')    NOT NULL,
    RWK_STOP_OPER               VARCHAR2(10)     DEFAULT(' ')    NOT NULL,
    RWK_RET_FLOW                VARCHAR2(20)     DEFAULT(' ')    NOT NULL,
    RWK_RET_FLOW_SEQ_NUM        NUMBER(6)        DEFAULT(0)      NOT NULL,
    RWK_RET_OPER                VARCHAR2(10)     DEFAULT(' ')    NOT NULL,
    RWK_END_FLOW                VARCHAR2(20)     DEFAULT(' ')    NOT NULL,
    RWK_END_FLOW_SEQ_NUM        NUMBER(6)        DEFAULT(0)      NOT NULL,
    RWK_END_OPER                VARCHAR2(10)     DEFAULT(' ')    NOT NULL,
    RWK_RET_CLEAR_FLAG          CHAR(1)          DEFAULT(' ')    NOT NULL,
    LOCAL_REWORK_FLAG           CHAR(1)          DEFAULT(' ')    NOT NULL,
    RWK_USER_ID                 VARCHAR2(20)     DEFAULT(' ')    NOT NULL,
    RWK_COMMENT                 VARCHAR2(400)    DEFAULT(' ')    NOT NULL,
    USER_ID_1                   VARCHAR2(20)     DEFAULT(' ')    NOT NULL,
    USER_TIME_1                 VARCHAR2(14)     DEFAULT(' ')    NOT NULL,
    USER_COMMENT_1              VARCHAR2(400)    DEFAULT(' ')    NOT NULL,
    USER_ID_2                   VARCHAR2(20)     DEFAULT(' ')    NOT NULL,
    USER_TIME_2                 VARCHAR2(14)     DEFAULT(' ')    NOT NULL,
    USER_COMMENT_2              VARCHAR2(400)    DEFAULT(' ')    NOT NULL,
    USER_ID_3                   VARCHAR2(20)     DEFAULT(' ')    NOT NULL,
    USER_TIME_3                 VARCHAR2(14)     DEFAULT(' ')    NOT NULL,
    USER_COMMENT_3              VARCHAR2(400)    DEFAULT(' ')    NOT NULL
) TABLESPACE HISTORY_DATA_TS;

ALTER TABLE MWIPLOTRWK
ADD CONSTRAINT MWIPLOTRWK_PK PRIMARY KEY
(
    LOT_ID,
    HIST_SEQ
) USING INDEX TABLESPACE HISTORY_IDX_TS;

SELECT 
    LOT_ID                ,
    HIST_SEQ              ,
    TRAN_TIME             ,
    HIST_DEL_FLAG         ,
    FACTORY               ,
    MAT_ID                ,
    MAT_VER               ,
    FLOW                  ,
    FLOW_SEQ_NUM          ,
    OPER                  ,
    RES_ID                ,
    CAUSE_FLOW            ,
    CAUSE_OPER            ,
    CAUSE_RES_ID          ,
    QTY_1                 ,
    QTY_2                 ,
    QTY_3                 ,
    RWK_CODE              ,
    RWK_COUNT             ,
	0                     ,
    FLOW                  ,
    FLOW_SEQ_NUM          ,
    OPER                  ,
	' '                   ,
    RWK_RET_FLOW          ,
    RWK_RET_FLOW_SEQ_NUM  ,
    RWK_RET_OPER          ,
    RWK_END_FLOW          ,
    RWK_END_FLOW_SEQ_NUM  ,
    RWK_END_OPER          ,
    RWK_RET_CLEAR_FLAG    ,
	' '                   ,
    RWK_USER_ID           ,
    RWK_COMMENT           ,
    USER_ID_1             ,
    USER_TIME_1           ,
    USER_COMMENT_1        ,
    USER_ID_2             ,
    USER_TIME_2           ,
    USER_COMMENT_2        ,
    USER_ID_3             ,
    USER_TIME_3           ,
    USER_COMMENT_3
FROM MWIPLOTRWK_OLD);


DECLARE
     V_FLOW    		VARCHAR2(20);
     V_FLOW_SEQ    	NUMBER(10);
     V_OPER    		VARCHAR2(10);
BEGIN
	 FOR REC IN (
			SELECT * 
			FROM MWIPLOTRWK
			ORDER BY LOT_ID, HIST_SEQ
	 )
     LOOP


        BEGIN
            SELECT OLD_FLOW, OLD_FLOW_SEQ_NUM, OLD_OPER 
            INTO V_FLOW, V_FLOW_SEQ, V_OPER
            FROM MWIPLOTHIS
            WHERE LOT_ID = REC.LOT_ID
                AND HIST_SEQ = REC.HIST_SEQ;
    
            UPDATE MWIPLOTRWK 
            SET FLOW = V_FLOW, FLOW_SEQ_NUM = V_FLOW_SEQ, OPER = V_OPER
            WHERE LOT_ID = REC.LOT_ID
                AND HIST_SEQ = REC.HIST_SEQ;

            EXCEPTION
                WHEN NO_DATA_FOUND THEN  -- catches all 'no data found' errors
                    DBMS_OUTPUT.PUT_LINE (' exception no_data_found' );
        END;
     END LOOP;
END ;
/

DECLARE
     V_QUEUE_TIME_UNIT		CHAR(1);
     V_UPPER_WARN_QUE_TIME	NUMBER(6);
     V_LOWER_WARN_QUE_TIME	NUMBER(6);
     V_UPPER_ERR_QUE_TIME	NUMBER(6);
     V_LOWER_ERR_QUE_TIME	NUMBER(6);
BEGIN
    FOR REC IN (
      SELECT * 
      FROM MWIPQTMDEF
      ORDER BY FACTORY, MAT_ID, MAT_VER, FLOW, FLOW_SEQ_NUM, OPER, FROM_FLOW, FROM_FLOW_SEQ_NUM, FROM_OPER
    )
  
    LOOP
      BEGIN
        SELECT UPPER_WARN_QUE_TIME, LOWER_WARN_QUE_TIME, UPPER_ERR_QUE_TIME, LOWER_ERR_QUE_TIME 
        INTO V_UPPER_WARN_QUE_TIME, V_LOWER_WARN_QUE_TIME, V_UPPER_ERR_QUE_TIME, V_LOWER_ERR_QUE_TIME
        FROM MWIPQTMDEF QTIME
        WHERE EXISTS ( SELECT * FROM MBASGLBDEF QUNIT WHERE REC.FACTORY=QUNIT.FACTORY AND QUNIT.VALUE_1='H' AND QUNIT.OPTION_NAME='MP_QueueTimeUnit')
          AND QTIME.FACTORY = REC.FACTORY
          AND QTIME.MAT_ID = REC.MAT_ID
          AND QTIME.MAT_VER = REC.MAT_VER
          AND QTIME.FLOW = REC.FLOW
          AND QTIME.FLOW_SEQ_NUM = REC.FLOW_SEQ_NUM
          AND QTIME.OPER = REC.OPER
          AND QTIME.FROM_FLOW = REC.FROM_FLOW
          AND QTIME.FROM_FLOW_SEQ_NUM = REC.FROM_FLOW_SEQ_NUM
          AND QTIME.FROM_OPER = REC.FROM_OPER;
          
        UPDATE MWIPQTMDEF 
        SET UPPER_WARN_QUE_TIME = V_UPPER_WARN_QUE_TIME * 60, LOWER_WARN_QUE_TIME = V_LOWER_WARN_QUE_TIME * 60, UPPER_ERR_QUE_TIME = V_UPPER_ERR_QUE_TIME * 60, LOWER_ERR_QUE_TIME = V_LOWER_ERR_QUE_TIME * 60 
        WHERE FACTORY = REC.FACTORY
          AND MAT_ID = REC.MAT_ID
          AND MAT_VER = REC.MAT_VER
          AND FLOW = REC.FLOW
          AND FLOW_SEQ_NUM = REC.FLOW_SEQ_NUM
          AND OPER = REC.OPER
          AND FROM_FLOW = REC.FROM_FLOW
          AND FROM_FLOW_SEQ_NUM = REC.FROM_FLOW_SEQ_NUM
          AND FROM_OPER = REC.FROM_OPER;
        EXCEPTION
          WHEN NO_DATA_FOUND THEN  -- catches all 'no data found' errors
            DBMS_OUTPUT.PUT_LINE (' exception no_data_found' );
        END;
     END LOOP;
END ;
/

